/* strerror(code) copied into buf[0, max); its length */
static int _proc_error_text(int code, char *buf, int max) {
  const char *s = strerror(code);
  size_t n = s ? strlen(s) : 0;
  if (n > (size_t)max) n = (size_t)max;
  if (n) memcpy(buf, s, n);
  return (int)n;
}

